# Intune detection script for the Atlantiraptor agent (Win32 app >
# Detection rules > Use a custom detection script). Generated by the
# Atlantiraptor console on {{.Generated}}.
#
# Intune treats the app as installed when this exits with 0 and writes
# something to standard output.
$svc = Get-Service -Name 'Atlantiraptor' -ErrorAction SilentlyContinue
$root = if ($env:ProgramW6432) { $env:ProgramW6432 } else { $env:ProgramFiles }
$exe = Join-Path $root 'Atlant Security\Atlantiraptor\Atlantiraptor.exe'
if ($svc -and (Test-Path -LiteralPath $exe)) {
    Write-Output "Atlantiraptor is installed (service $($svc.Status))."
    exit 0
}
exit 1
